  snapshot(workspace, ctx) {
    return withLock(this.#chains, workspace.key, async () => {
      if (ctx.previousRef !== undefined) assertSafeRef(ctx.previousRef)
      let sha = (await this.#git(workspace.cwd, ['stash', 'create'])).stdout.trim()
